      "tipo": "explicacao_tecnica",
      "achados": [
        {
          "proposicao": "Um FPSO é descrito como unidade flutuante de produção, armazenamento e transferência de petróleo, formada por subsistemas de processamento primário destinados a separar óleo, gás e água.",
          "trechos": [
            "E6bd559ee2a518b46:1395:2095"
          ],
          "condicoes": [
            "No enquadramento geral de uma unidade offshore do tipo FPSO."
          ],
          "limites": [
            "É definição introdutória; não aprofunda bombas, válvulas, comunicação entre equipes nem estabilidade durante offloading."
          ]
        },
        {
          "proposicao": "O processamento das fases em um FPSO visa enquadrá-las para finalidades distintas: transferência de óleo e gás e descarte de água.",
          "trechos": [
            "E6bd559ee2a518b46:1395:2095"
          ],
          "condicoes": [
            "Aplicável ao processamento primário de fluidos no FPSO."
